from AlgorithmImports import *
import math


class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.prev_spy_close = None
        self.prev_spy_sma = None
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        for symbol in self.symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        spy_cross_above = False
        spy_cross_below = False
        if self.sma.IsReady and self.prev_spy_close is not None and self.prev_spy_sma is not None:
            sma_value = self.sma.Current.Value
            if self.prev_spy_close <= self.prev_spy_sma and spy_close > sma_value:
                spy_cross_above = True
            if self.prev_spy_close >= self.prev_spy_sma and spy_close < sma_value:
                spy_cross_below = True

        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        aapl_sell_signal = self.rsi.IsReady and self.rsi.Current.Value > 60

        if self.Portfolio[self.spy].Quantity > 0 and spy_cross_below:
            self.Liquidate(self.spy)

        if self.Portfolio[self.aapl].Quantity > 0 and aapl_sell_signal:
            self.Liquidate(self.aapl)

        if self.Portfolio[self.spy].Quantity == 0 and spy_cross_above:
            target_value = 0.4 * self.Portfolio.TotalPortfolioValue
            qty = math.floor(target_value / spy_close)
            if qty > 0:
                self.MarketOrder(self.spy, qty)

        if self.Portfolio[self.aapl].Quantity == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                qty = math.floor(20000 / aapl_close)
                if qty > 0:
                    self.MarketOrder(self.aapl, qty)

        self.prev_spy_close = spy_close
        self.prev_spy_sma = self.sma.Current.Value if self.sma.IsReady else None
        self.prev_aapl_close = aapl_close

