from AlgorithmImports import *


class MultiStrategyDailySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for t in tickers:
            self.symbols[t] = self.AddEquity(t, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Indicators
        self.sma = self.SMA(self.spy, 50, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Strategy A (SPY) cross-tracking state
        self.spy_prev_close = None
        self.spy_prev_sma = None
        self.slotA_shares = 0

        # Strategy B (AAPL) red-streak tracking state
        self.aapl_close_history = []
        self.slotB_shares = 0

    def OnData(self, data: Slice):
        # Skip the entire day if any subscribed ticker's bar is missing
        for sym in self.symbols.values():
            if not data.Bars.ContainsKey(sym):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # --------- Slot 1: Strategy A (SPY, SMA cross) ---------
        if self.sma.IsReady:
            sma_value = self.sma.Current.Value

            if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                crosses_above = (self.spy_prev_close <= self.spy_prev_sma) and (spy_close > sma_value)
                crosses_below = (self.spy_prev_close >= self.spy_prev_sma) and (spy_close < sma_value)

                # Sell before buy
                if self.slotA_shares > 0:
                    if crosses_below:
                        self.MarketOrder(self.spy, -self.slotA_shares)
                        self.slotA_shares = 0
                elif self.slotA_shares == 0:
                    if crosses_above:
                        portfolio_value = self.Portfolio.TotalPortfolioValue
                        target_value = 0.40 * portfolio_value
                        shares = int(target_value // spy_close)
                        if shares > 0:
                            self.MarketOrder(self.spy, shares)
                            self.slotA_shares += shares

            self.spy_prev_close = spy_close
            self.spy_prev_sma = sma_value

        # --------- Slot 2: Strategy B (AAPL, red streak / RSI) ---------
        self.aapl_close_history.append(aapl_close)
        if len(self.aapl_close_history) > 10:
            self.aapl_close_history.pop(0)

        if self.rsi.IsReady:
            rsi_value = self.rsi.Current.Value

            # Sell before buy
            if self.slotB_shares > 0:
                if rsi_value > 60:
                    self.MarketOrder(self.aapl, -self.slotB_shares)
                    self.slotB_shares = 0
            elif self.slotB_shares == 0:
                if self._is_red_streak(self.aapl_close_history, 3):
                    cash = self.Portfolio.Cash
                    if cash >= 20000:
                        shares = int(20000 // aapl_close)
                        if shares > 0:
                            self.MarketOrder(self.aapl, shares)
                            self.slotB_shares += shares

    def _is_red_streak(self, closes, n):
        if len(closes) < n + 1:
            return False
        window = closes[-(n + 1):]
        for i in range(len(window) - 1):
            if not (window[i + 1] < window[i]):
                return False
        return True

