from AlgorithmImports import *
import math


class DualStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Indicators
        self.sma_spy = self.SMA(self.spy, 50, Resolution.Daily)
        self.rsi_aapl = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Previous-day state for cross detection
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # AAPL red-streak state
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        # Strategy lots (share counts owned by each strategy)
        self.lotA_shares = 0  # Strategy A -> SPY
        self.lotB_shares = 0  # Strategy B -> AAPL

    def OnData(self, data: Slice):
        # Skip the entire day if any subscribed ticker's bar is missing
        for symbol in self.all_symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        today_spy_close = data.Bars[self.spy].Close
        today_aapl_close = data.Bars[self.aapl].Close

        # Update AAPL red-day streak using today's close vs previous close
        if self.prev_aapl_close is not None:
            if today_aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # ---------------- Slot 1: Strategy A (SPY, SMA cross) ----------------
        if self.sma_spy.IsReady:
            today_spy_sma = self.sma_spy.Current.Value

            if self.lotA_shares > 0:
                if self.prev_spy_close is not None and self.prev_spy_sma is not None:
                    crosses_below = (self.prev_spy_close >= self.prev_spy_sma) and (today_spy_close < today_spy_sma)
                    if crosses_below:
                        self.MarketOrder(self.spy, -self.lotA_shares, tag="A")
            elif self.lotA_shares == 0:
                if self.prev_spy_close is not None and self.prev_spy_sma is not None:
                    crosses_above = (self.prev_spy_close <= self.prev_spy_sma) and (today_spy_close > today_spy_sma)
                    if crosses_above:
                        invest_amount = 0.40 * self.Portfolio.TotalPortfolioValue
                        shares = math.floor(invest_amount / today_spy_close)
                        if shares > 0:
                            self.MarketOrder(self.spy, shares, tag="A")
        else:
            today_spy_sma = None

        # ---------------- Slot 2: Strategy B (AAPL, red streak / RSI) ----------------
        if self.lotB_shares > 0:
            if self.rsi_aapl.IsReady:
                rsi_value = self.rsi_aapl.Current.Value
                if rsi_value > 60:
                    self.MarketOrder(self.aapl, -self.lotB_shares, tag="B")
        elif self.lotB_shares == 0:
            if self.aapl_red_streak >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = math.floor(20000 / today_aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares, tag="B")

        # Persist state for next bar's comparisons
        self.prev_spy_close = today_spy_close
        self.prev_spy_sma = today_spy_sma if today_spy_sma is not None else self.prev_spy_sma
        self.prev_aapl_close = today_aapl_close

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status != OrderStatus.Filled and orderEvent.Status != OrderStatus.PartiallyFilled:
            return

        order = self.Transactions.GetOrderById(orderEvent.OrderId)
        tag = order.Tag
        fill_qty = int(orderEvent.FillQuantity)

        if tag == "A":
            self.lotA_shares += fill_qty
        elif tag == "B":
            self.lotB_shares += fill_qty

