class ParallelSlotStrategyAlgorithm(QCAlgorithm):

    SPY_SMA_PERIOD = 50
    AAPL_RSI_PERIOD = 14
    AAPL_RED_STREAK_REQUIRED = 3
    AAPL_RSI_SELL_LEVEL = 60
    AAPL_BUY_DOLLARS = 20000
    SPY_INVEST_PCT = 0.40

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, self.SPY_SMA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, self.AAPL_RSI_PERIOD, MovingAverageType.Wilders, Resolution.Daily)

        self.prev_spy_close = None
        self.prev_spy_sma = None
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        self.strategyA_shares = 0
        self.strategyB_shares = 0

    def OnData(self, data: Slice):
        for symbol in self.all_symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # Strategy A: SPY moving-average crossover
        if self.spy_sma.IsReady:
            spy_sma_value = self.spy_sma.Current.Value

            if self.prev_spy_sma is not None:
                cross_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > spy_sma_value)
                cross_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close < spy_sma_value)

                if self.strategyA_shares > 0:
                    if cross_below:
                        self.MarketOrder(self.spy, -self.strategyA_shares)
                        self.strategyA_shares = 0

                if self.strategyA_shares == 0:
                    if cross_above:
                        target_value = self.SPY_INVEST_PCT * self.Portfolio.TotalPortfolioValue
                        shares = math.floor(target_value / spy_close)
                        if shares > 0:
                            self.MarketOrder(self.spy, shares)
                            self.strategyA_shares = shares

            self.prev_spy_sma = spy_sma_value
        else:
            self.prev_spy_sma = None

        # Strategy B: AAPL red-streak buy / RSI sell
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            if self.strategyB_shares > 0:
                if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > self.AAPL_RSI_SELL_LEVEL:
                    self.MarketOrder(self.aapl, -self.strategyB_shares)
                    self.strategyB_shares = 0

            if self.strategyB_shares == 0:
                if self.aapl_red_streak >= self.AAPL_RED_STREAK_REQUIRED:
                    available_cash = self.Portfolio.Cash
                    if available_cash >= self.AAPL_BUY_DOLLARS:
                        shares = math.floor(self.AAPL_BUY_DOLLARS / aapl_close)
                        if shares > 0:
                            self.MarketOrder(self.aapl, shares)
                            self.strategyB_shares = shares
        else:
            self.aapl_red_streak = 0

        self.prev_spy_close = spy_close
        self.prev_aapl_close = aapl_close

