                        self.MarketOrder(self.spy, qty)
                        self.a_shares = qty

        # ---------- Strategy B: SELL before BUY ----------
        if self.b_shares > 0:
            if self.b_prev_rsi is not None:
                crosses_above_60 = (self.b_prev_rsi <= 60) and (rsi_value > 60)
                if crosses_above_60:
                    self.MarketOrder(self.aapl, -self.b_shares)
                    self.b_shares = 0
        else:
            if self.b_red_streak >= 3:
                cash_needed = 20000.0
                if self.Portfolio.Cash >= cash_needed:
                    qty = int(np.floor(cash_needed / aapl_close))
                    if qty > 0:
                        self.MarketOrder(self.aapl, qty)
                        self.b_shares = qty

        # ---------- Update previous-value state for next bar ----------
        self.a_prev_close = spy_close
        self.a_prev_sma = sma_value
        self.b_prev_close = aapl_close
        self.b_prev_rsi = rsi_value

