        for t in tickers:
            self.symbols[t] = self.AddEquity(t, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Indicators
        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, Resolution.Daily, MovingAverageType.Wilders)

        # Cross-detection state (previous bar values)
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # Red-streak state
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        # Private lots per strategy
        self.a_shares = 0  # Strategy A (SPY)
        self.b_shares = 0  # Strategy B (AAPL)

    def OnData(self, data: Slice):
        # Skip the entire day if any subscribed ticker's bar is missing
        for sym in self.symbols.values():
            if not data.Bars.ContainsKey(sym):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # --- Update continuously-computed market-state quantities ---

        # AAPL red/green streak
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Determine SPY cross vs 100-day SMA (needs previous day's close & SMA, and SMA ready)
        spy_sma_ready = self.spy_sma.IsReady
        spy_crosses_above = False
        spy_crosses_below = False
        if spy_sma_ready and self.prev_spy_close is not None and self.prev_spy_sma is not None:
            today_spy_sma = self.spy_sma.Current.Value
            if self.prev_spy_close <= self.prev_spy_sma and spy_close > today_spy_sma:
                spy_crosses_above = True
            if self.prev_spy_close >= self.prev_spy_sma and spy_close < today_spy_sma:
                spy_crosses_below = True

        aapl_rsi_ready = self.aapl_rsi.IsReady

        # =========================
        # Strategy A (SPY) - sell before buy
        # =========================
        if self.a_shares > 0:
            if spy_crosses_below:
                self.MarketOrder(self.spy, -self.a_shares)
                self.a_shares = 0
        else:
            if spy_sma_ready and spy_crosses_above:
                invest_amount = 0.40 * self.Portfolio.TotalPortfolioValue
                shares = int(invest_amount // spy_close)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.a_shares += shares

        # =========================
        # Strategy B (AAPL) - sell before buy
        # =========================
        if self.b_shares > 0:
            if aapl_rsi_ready and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.b_shares)
                self.b_shares = 0
        else:
            if self.aapl_red_streak >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(20000 // aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.b_shares += shares

        # --- Roll state forward for next bar's cross detection ---
        self.prev_spy_close = spy_close
        if spy_sma_ready:
            self.prev_spy_sma = self.spy_sma.Current.Value
        self.prev_aapl_close = aapl_close
